import React, { useState } from 'react';
import './PhotosPage.css';

const PhotosPage = () => {
  const [selectedCategory, setSelectedCategory] = useState('all');

  const photos = [
    {
      id: 1,
      title: "Modern Kitchen Design",
      category: "kitchen",
      image: "https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400&h=300&fit=crop",
      professional: "Sarah Johnson Design",
      location: "San Francisco, CA",
      rating: 4.8
    },
    {
      id: 2,
      title: "Luxury Bathroom",
      category: "bath",
      image: "https://images.unsplash.com/photo-1620626011761-996317b8d101?w=400&h=300&fit=crop",
      professional: "Elite Interiors",
      location: "New York, NY",
      rating: 4.9
    },
    {
      id: 3,
      title: "Cozy Bedroom",
      category: "bedroom",
      image: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=400&h=300&fit=crop",
      professional: "Dream Spaces",
      location: "Los Angeles, CA",
      rating: 4.7
    },
    {
      id: 4,
      title: "Contemporary Living Room",
      category: "living",
      image: "https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=400&h=300&fit=crop",
      professional: "Modern Home Studio",
      location: "Chicago, IL",
      rating: 4.6
    }
  ];

  const categories = ['all', 'kitchen', 'bath', 'bedroom', 'living', 'dining', 'outdoor'];

  const filteredPhotos = selectedCategory === 'all' 
    ? photos 
    : photos.filter(photo => photo.category === selectedCategory);

  return (
    <div className="photos-page">
      <div className="container">
        <h1 className="page-title">Photo Gallery</h1>
        <p className="page-subtitle">Browse thousands of professional home photos for inspiration</p>
        
        <div className="category-filters">
          {categories.map(category => (
            <button
              key={category}
              className={`filter-btn ${selectedCategory === category ? 'active' : ''}`}
              onClick={() => setSelectedCategory(category)}
            >
              {category.charAt(0).toUpperCase() + category.slice(1)}
            </button>
          ))}
        </div>
        
        <div className="photos-grid">
          {filteredPhotos.map(photo => (
            <div key={photo.id} className="photo-card">
              <div className="photo-image">
                <img src={photo.image} alt={photo.title} />
                <div className="photo-overlay">
                  <button className="save-btn">💖</button>
                </div>
              </div>
              
              <div className="photo-info">
                <h3 className="photo-title">{photo.title}</h3>
                <p className="photo-professional">{photo.professional}</p>
                <p className="photo-location">{photo.location}</p>
                <div className="photo-rating">
                  <span className="stars">⭐ {photo.rating}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default PhotosPage;
